a<-commandArgs(TRUE);root<-a[1];td<-file.path(root,'supplementary_tables');fd<-file.path(root,'figures');dir.create(fd,showWarnings=FALSE)
dec<-read.csv(file.path(td,'S36_score_deciles.csv'));ctrl<-read.csv(file.path(td,'S37_matched_retention_controls.csv'));ci<-read.csv(file.path(td,'S38_control_uncertainty.csv'));nul<-read.csv(file.path(td,'S39_null_stability.csv'));prof<-read.csv(file.path(td,'S40_null_profile_diagnostics.csv'))
labels<-c(Astro='Astrocytes',Excit='Excitatory neurons',Inhib='Inhibitory neurons',Oligo='Oligodendrocytes',OPC='Oligodendrocyte precursor cells',Immune='Immune cells',Vascular='Vascular cells')
cols<-c(Excit='#236BB2',Inhib='#A34790',Oligo='#369872',Astro='#CA8B2A',OPC='#5DAEB5',Immune='#A55535',Vascular='#757575')
if(length(a)<2L || a[2]!='--figures-only'){
summary<-list();set.seed(20261022)
stat<-function(z)c(recovery=mean(z$median_recovery,na.rm=TRUE),precision=if(sum(z$calls))sum(z$TP)/sum(z$calls)else NA_real_)
for(z in split(dec,paste(dec$setting,dec$cell_type,dec$decile))){b<-replicate(2000,stat(z[sample(seq_len(nrow(z)),nrow(z),TRUE),]));for(metric in rownames(b)){v<-b[metric,];q<-if(any(is.finite(v)))quantile(v[is.finite(v)],c(.025,.975),names=FALSE)else c(NA,NA);summary[[length(summary)+1]]<-data.frame(setting=z$setting[1],cell_type=z$cell_type[1],decile=z$decile[1],metric=metric,estimate=stat(z)[metric],lower=q[1],upper=q[2],cohorts=nrow(z),profiles=sum(z$selected),calls=sum(z$calls),TP=sum(z$TP),FP=sum(z$FP),bootstrap_finite=sum(is.finite(v)))}}
s<-do.call(rbind,summary);write.csv(s,file.path(td,'S41_score_decile_uncertainty.csv'),row.names=FALSE,na='')
}else s<-read.csv(file.path(td,'S41_score_decile_uncertainty.csv'))
draw<-function(name,width,height,fun){for(ext in c('pdf','png')){if(ext=='pdf')pdf(file.path(fd,paste0(name,'.pdf')),width,height,useDingbats=FALSE)else png(file.path(fd,paste0(name,'.png')),width=width,height=height,units='in',res=180);fun();dev.off()}}
decplot<-function(metric,types,title,legend_on=TRUE){plot(NA,xlim=c(1,10),ylim=c(0,1),xlab='Score group (1 = highest priority)',ylab=if(metric=='precision')'Precision among eQTL calls'else'Mean cohort median recovery',main=title,las=1);for(ct in types){ z<-s[s$setting=='N120_H30'&s$cell_type==ct&s$metric==metric,];z<-z[order(z$decile),];segments(z$decile,z$lower,z$decile,z$upper,col=adjustcolor(cols[ct],.4));lines(z$decile,z$estimate,type='o',pch=16,col=cols[ct],lwd=2)};if(legend_on)legend('bottomleft',labels[types],col=cols[types],lty=1,pch=16,bty='n',cex=.72)}
draw('Figure_7_prioritization_evidence',11,8,function(){par(mfrow=c(2,2),mar=c(4.5,4.8,3,1),mgp=c(2.8,.8,0));decplot('recovery',c('Excit','Inhib','Oligo'),'A  Expression recovery by score');decplot('precision',c('Excit','Inhib','Oligo'),'B  eQTL correctness by score');
 par(mar=c(4.5,8,3,1));z<-subset(ci,setting=='N120_H30'&cell_type=='Excit'&metric=='precision'&method!='GAM6');z<-z[match(c('Random','Expected_count','Contribution'),z$method),];plot(z$GAM6_minus_method,1:3,xlim=range(c(-.07,.22,z$difference_lower,z$difference_upper)),ylim=c(.6,3.4),yaxt='n',ylab='',xlab='Precision difference: prioritization minus control',main='C  Equal-budget comparison',pch=16,col=cols['Excit']);axis(2,1:3,c('Random','Expected counts','Contribution'),las=1,cex.axis=.8);segments(z$difference_lower,1:3,z$difference_upper,1:3,col=cols['Excit'],lwd=2);abline(v=0,lty=2,col='gray50');
 par(mar=c(4.5,4.8,3,1));z<-subset(ctrl,setting=='N120_H30'&cell_type=='Excit');av<-aggregate(cbind(TP,FP)~method+id,z,mean);av<-aggregate(cbind(TP,FP)~method,av,sum);av<-av[match(c('GAM6','Contribution','Expected_count','Random'),av$method),];b<-barplot(t(as.matrix(av[c('TP','FP')])),col=c(cols['Excit'],'#D56554'),names.arg=c('Prioritization','Contribution','Expected\ncounts','Random'),cex.names=.75,ylab='Calls across five cohorts',main='D  Correct calls and false calls',ylim=c(0,65));legend('topright',c('Injected target','Non-injected'),fill=c(cols['Excit'],'#D56554'),bty='n',cex=.75);mtext('Each method retains 80 of 200 pairs per type and cohort',side=1,line=3.4,cex=.72)
})
draw('Figure_S16_all_type_score_groups',11,9,function(){par(mfrow=c(2,1),mar=c(4,12,3,1));cts<-names(labels);for(metric in c('recovery','precision')){z<-s[s$setting=='N120_H30'&s$metric==metric,];mat<-matrix(NA_real_,10,7);for(i in seq_len(nrow(z)))mat[z$decile[i],match(z$cell_type[i],cts)]<-z$estimate[i];image(1:10,1:7,mat,zlim=c(0,1),col=colorRampPalette(c('white','#236BB2'))(101),axes=FALSE,xlab='Score group (1 = highest priority)',ylab='',main=if(metric=='recovery')'A  Expression recovery by score group'else'B  eQTL precision by score group');axis(1,1:10);axis(2,1:7,labels[cts],las=1,cex.axis=.8);for(i in 1:10)for(j in 1:7)text(i,j,if(is.finite(mat[i,j]))sprintf('%.2f',mat[i,j])else'NA',col=if(is.finite(mat[i,j])&&mat[i,j]>.65)'white'else'black',cex=.75)}})
draw('Figure_S17_equal_budget_controls',12,7,function(){par(mfrow=c(1,2),mar=c(9,11,3,1));settings<-unique(ci$setting);cts<-names(labels);for(metric in c('precision','median_recovery')){z<-ci[ci$method=='Contribution'&ci$metric==metric,];mat<-matrix(NA,length(settings),length(cts));for(i in 1:nrow(z))mat[match(z$setting[i],settings),match(z$cell_type[i],cts)]<-z$GAM6_minus_method[i];lim<-max(abs(mat),na.rm=TRUE);image(seq_along(settings),seq_along(cts),mat,zlim=c(-lim,lim),col=colorRampPalette(c('#B24442','white','#236BB2'))(101),axes=FALSE,xlab='',ylab='',main=paste('GAM6 minus contribution:',if(metric=='precision')'precision'else'recovery'));axis(1,seq_along(settings),gsub('N120_H30_','',gsub('lowExcit','lower abundance',settings)),las=2,cex.axis=.8);axis(2,seq_along(cts),labels[cts],las=1,cex.axis=.8);for(i in seq_along(settings))for(j in seq_along(cts))text(i,j,if(is.finite(mat[i,j]))sprintf('%+.2f',mat[i,j])else'NA',cex=.7)}})
draw('Figure_S18_null_stability',11,8,function(){par(mfrow=c(2,2),mar=c(4.5,4.5,3,1),mgp=c(2.8,.8,0));z<-subset(nul,record=='null_trait'&engine=='CDSeq2'&normalization=='logCPM');z39<-subset(z,n==39);plot(z39$trait,z39$calls,type='h',col=cols['Excit'],xlab='Null phenotype',ylab='Calls across 14,000 tests',main='A  Rare large rejection bursts');z40<-subset(z,n==40);points(z40$trait,z40$calls,pch=1,col='#D56554');legend('topleft',c('39 donors (primary)','40 donors'),col=c(cols['Excit'],'#D56554'),lty=c(1,NA),pch=c(NA,1),bty='n',cex=.8);
 z<-subset(nul,record=='expression_structure'&normalization=='logCPM'&n==39);barplot(z$pc1_fraction,names.arg=z$engine,col=c(cols['Excit'],'gray60'),ylim=c(0,.5),ylab='Fraction of standardized profile variation',main='B  Shared expression pattern');
 z<-subset(nul,record=='leave_one_more_donor');plot(NA,xlim=c(1,40),ylim=c(0,max(z$calls)),xlab='Additionally omitted donor index',ylab='Calls (38-donor diagnostic)',main='C  Donor influence');cc<-c('#236BB2','#369872','#A34790');for(i in seq_along(unique(z$trait))){zz<-z[z$trait==unique(z$trait)[i],];lines(zz$omitted_donor,zz$calls,type='o',pch=16,cex=.4,col=cc[i])};abline(v=38,lty=2,col='gray50');legend('bottomleft',paste('Null',unique(z$trait)),col=cc,lty=1,bty='n',cex=.75);
 z<-subset(nul,record=='null_trait'&engine=='CDSeq2'&n==39);sums<-aggregate(calls~normalization,z,mean);barplot(sums$calls,names.arg=sums$normalization,col=c('gray60',cols['Excit'],'#D56554'),ylab='Mean calls per null phenotype',main='D  Transformation sensitivity');mtext('Diagnostic transformations; primary analysis unchanged',side=1,line=3,cex=.7)
})
cat('New figures and decile confidence summaries complete.\n')
